app std-rich-editor "1.0.0"
"std-rich-editor — wiki/CMS Notion-style block editor. Browses documents in `browsing`; opens the rich-block-editor on a selected row; persists block edits + publish status. `BlockEdit` is a rebindable single-row IN-PLACE body editor: an organism embeds it where the content belongs, rebinds it to its own entity (WikiPage, Note, …), hands it the row's id + blocksJson via OPEN, and routes the emitted BLOCKS_SAVED into its own persistor — this atom never fetches or persists. The read-only body is itself the edit affordance; an empty row paints an empty state that starts the first block; and OPEN_DRAFT opens straight into the authoring editor for a row that was just minted blank (document-first creation)."
;; @capabilities "notes app, note-taking, journal, personal journal entries, document editor, write and organize notes"
type BlockSpec = { type : string!, content : string, id : string }
type ObjectSpec = { id : string, label : string, value : string }
orbital DocumentOrbital {
    type DocumentLoaded = Event { data : [Document] } "Fired when the documents collection finishes loading"

    type DocumentLoadFailed = Event { error : string, code : string } "Fired when the documents collection fails to load"

    type DocumentSaved = Event { row : Document } "Fired after a document's block content persists successfully"

    type DocumentPublished = Event { row : Document } "Fired after a document's status flips to published"

    type DocumentSaveFailed = Event { error : string, code : string } "Fired when persisting a document edit fails"

  entity Document [persistent: documents] {
    id : string!
    title : string! @description "The human-readable name of the document." @synonyms "name, heading, label"
    blocksJson : [BlockSpec] @description "Serialized representation of the document's content blocks." @synonyms "content, data, structure, blocks"
    authorId : string @description "Unique identifier of the user who created the document." @synonyms "creatorId, userId, ownerId"
    parentId : string @description "Reference to the parent document or container." @synonyms "parent, container, owner"
    kind : "page" | "doc" | "post" @description "Specifies the document type." @synonyms "type, documentType, category" = page
    status : "draft" | "published" | "archived" @description "Indicates the current state of the document." @synonyms "state, condition, lifecycle" = draft
    version : number @description "Represents the version number of the document." @synonyms "revision, release, iteration" = 1
    createdAt : string
    updatedAt : string
  }

  trait DocumentEdit -> Document [interaction, collection] {
    initial: loading

    state loading {
      INIT -> loading
        (fetch Document {
          emit: { failure: DocumentLoadFailed, success: DocumentLoaded }
        })
        (render-ui main {
          align: center
          children: [{ type: spinner }, {
            color: muted
            content: "Loading documents…"
            type: typography
            variant: caption
          }]
          className: py-12
          direction: vertical
          gap: md
          type: stack
        })
      DocumentLoaded -> browsing
        (render-ui main {
          children: [{
            align: center
            children: [{ name: file-text, type: icon }, {
              content: @config.title
              type: typography
              variant: h3
            }]
            direction: horizontal
            gap: sm
            type: stack
          }, { type: divider }, {
            cols: 1
            entity: ?data
            fields: [{
              label: Title
              name: title
              variant: caption
            }, {
              label: Kind
              name: kind
              variant: badge
            }, {
              label: Status
              name: status
              variant: badge
            }, {
              label: Version
              name: version
              variant: caption
            }, {
              format: date
              label: Updated
              name: updatedAt
              variant: caption
            }]
            gap: sm
            itemActions: [{
              event: OPEN
              icon: edit
              label: Open
              variant: primary
            }, {
              event: PUBLISH
              icon: send
              label: Publish
              variant: secondary
            }]
            look: @config.tableLook
            type: data-grid
          }]
          direction: vertical
          gap: md
          type: stack
        })
      DocumentSaved -> loading
        (fetch Document {
          emit: { failure: DocumentLoadFailed, success: DocumentLoaded }
        })
      DocumentPublished -> loading
        (fetch Document {
          emit: { failure: DocumentLoadFailed, success: DocumentLoaded }
        })
      DocumentSaveFailed -> error
        (render-ui main {
          message: ?error
          type: alert
          variant: error
        })
      DocumentLoadFailed -> error
        (render-ui main {
          message: ?error
          type: alert
          variant: error
        })
    }

    state browsing {
      ;; revisit re-fetches silently — landing state's own DocumentLoaded arm repaints
      INIT -> loading
        (fetch Document {
          emit: { failure: DocumentLoadFailed, success: DocumentLoaded }
        })
      OPEN -> editing
        (set @entity.id ?row.id)
        (set @entity.title ?row.title)
        (set @entity.blocksJson ?row.blocksJson)
        (set @entity.authorId ?row.authorId)
        (set @entity.parentId ?row.parentId)
        (set @entity.kind ?row.kind)
        (set @entity.status ?row.status)
        (set @entity.version ?row.version)
        (set @entity.createdAt ?row.createdAt)
        (set @entity.updatedAt ?row.updatedAt)
        (render-ui main {
          children: [{
            align: center
            children: [{
              action: CLOSE_VIEW
              label: Back
              type: button
              variant: ghost
            }, { name: file-text, type: icon }, {
              content: @entity.title
              type: typography
              variant: h3
            }, {
              label: @entity.status
              type: badge
              variant: secondary
            }]
            direction: horizontal
            gap: sm
            type: stack
          }, { type: divider }, {
            changeEvent: BLOCKS_CHANGE
            initialBlocks: @entity.blocksJson
            placeholder: "Start writing…"
            showToolbar: true
            type: rich-block-editor
          }, {
            align: center
            children: [{
              action: SAVE
              actionPayload: { id: @entity.id }
              label: Save
              type: button
              variant: primary
            }, {
              action: PUBLISH
              actionPayload: { id: @entity.id }
              label: Publish
              type: button
              variant: secondary
            }]
            direction: horizontal
            gap: sm
            type: stack
          }]
          direction: vertical
          gap: md
          type: stack
        })
      PUBLISH -> loading
        (set @entity.id ?id)
        (fetch Document {
          emit: { failure: DocumentLoadFailed, success: DocumentLoaded }
        })
        (render-ui main {
          align: center
          children: [{ type: spinner }, {
            color: muted
            content: "Publishing document…"
            type: typography
            variant: caption
          }]
          className: py-12
          direction: vertical
          gap: md
          type: stack
        })
    }

    state editing {
      BLOCKS_CHANGE -> editing
        (set @entity.blocksJson ?blocks)
      CLOSE_VIEW -> loading
        (fetch Document {
          emit: { failure: DocumentLoadFailed, success: DocumentLoaded }
        })
        (render-ui main {
          align: center
          children: [{ type: spinner }, {
            color: muted
            content: "Loading documents…"
            type: typography
            variant: caption
          }]
          className: py-12
          direction: vertical
          gap: md
          type: stack
        })
      SAVE -> loading
        (set @entity.id ?id)
        (persist update Document @entity {
          emit: { failure: DocumentSaveFailed, success: DocumentSaved }
        })
        (render-ui main {
          align: center
          children: [{ type: spinner }, {
            color: muted
            content: "Saving document…"
            type: typography
            variant: caption
          }]
          className: py-12
          direction: vertical
          gap: md
          type: stack
        })
      PUBLISH -> loading
        (set @entity.id ?id)
        (set @entity.status published)
        (persist update Document @entity {
          emit: { failure: DocumentSaveFailed, success: DocumentPublished }
        })
        (render-ui main {
          align: center
          children: [{ type: spinner }, {
            color: muted
            content: "Publishing document…"
            type: typography
            variant: caption
          }]
          className: py-12
          direction: vertical
          gap: md
          type: stack
        })
    }

    state error {
      INIT -> loading
        (fetch Document {
          emit: { failure: DocumentLoadFailed, success: DocumentLoaded }
        })
        (render-ui main { size: sm, type: spinner })
    }

    emits {
      OPEN {
        id : string!
        row : Document
      }
        @description "Signals the editor is being displayed."
        @synonyms "show, launch, reveal"
        @tier "domain"
      CLOSE_VIEW
        @description "Indicates the editor view is being closed."
        @synonyms "dismiss, hide, exit"
        @tier "domain"
      BLOCKS_CHANGE {
        blocks : [ObjectSpec]
      }
        @description "Signals that the content of a block has been modified."
        @synonyms "update, modify, changed, edit"
        @tier "domain"
      SAVE {
        id : string!
      }
        @description "Signals that changes have been saved."
        @synonyms "persist, update, commit"
        @tier "domain"
      PUBLISH {
        id : string!
      }
        @description "Signals that content has been published."
        @synonyms "publish, release, finalize"
        @tier "domain"
      DocumentLoaded {
        data : [Document]
      }
        @description "Signals that a document has been successfully loaded."
        @synonyms "loaded, fetched, retrieved"
        @tier "domain"
      DocumentLoadFailed {
        error : string
        code : string
      }
        @description "Indicates that loading a document failed."
        @synonyms "error, failure, problem, unsuccessful"
        @tier "internal"
      DocumentSaved {
        row : Document
      }
        @description "Signals that a document has been successfully saved."
        @synonyms "saved, persisted, updated"
        @tier "domain"
      DocumentPublished {
        row : Document
      }
        @description "Indicates a document has been successfully published."
        @synonyms "published, released, finalized"
        @tier "presentation"
      DocumentSaveFailed {
        error : string
        code : string
      }
        @description "Indicates that saving the document failed."
        @synonyms "error, failure, problem, unsuccessful"
        @tier "internal"
    }

    listens {
      OPEN {
        id : string!
        row : Document
      }
        @description "Indicates a rich editor view should be displayed."
        @synonyms "show, launch, reveal, display"
        @tier "domain"
      CLOSE_VIEW
        @description "Indicates the editor view is being dismissed."
        @synonyms "dismiss, hide, close, exit"
        @tier "domain"
      BLOCKS_CHANGE {
        blocks : [ObjectSpec]
      }
        @description "Indicates changes to the content of editable blocks."
        @synonyms "update, modify, edit"
        @tier "domain"
      SAVE {
        id : string!
      }
        @description "Indicates that changes have been saved."
        @synonyms "persist, update, commit"
        @tier "domain"
      PUBLISH {
        id : string!
      }
        @description "Indicates the document has been successfully published."
        @synonyms "publish, submit, finalize"
        @tier "domain"
      DocumentLoaded {
        data : [Document]
      }
        @description "Signals that a document has been successfully retrieved."
        @synonyms "loaded, fetched, retrieved"
        @tier "domain"
      DocumentLoadFailed {
        error : string
        code : string
      }
        @description "Indicates that loading a document failed."
        @synonyms "error, failure, problem, unsuccessful"
        @tier "internal"
      DocumentSaved {
        row : Document
      }
        @description "Indicates a document has been successfully saved."
        @synonyms "saved, updated, persisted"
        @tier "domain"
      DocumentPublished {
        row : Document
      }
        @description "Indicates a document has been successfully published."
        @synonyms "published, released, finalized"
        @tier "presentation"
      DocumentSaveFailed {
        error : string
        code : string
      }
        @description "Indicates a failure to save document changes."
        @synonyms "error, failure, problem, unsuccessful"
        @tier "internal"
    }

    config {
      title : string = Documents
        @label "Section title"
        @description "Heading shown above the document list"
        @tier "presentation"
      tableLook : "dense" | "spacious" | "striped" | "borderless" | "card-rows" = dense
        @label "Table look"
        @description "Layer 2 visual treatment for the data table rendered by this atom."
        @tier "presentation"
    }
  }

  ;; In-place body editor for one row. The composing organism embeds this
  ;; trait where the content belongs (`<trait.X />` inside its detail
  ;; render) and feeds it the loaded row through OPEN; the body paints
  ;; read-only AND is its own edit affordance — clicking it enters editing
  ;; with the authoring toolbar, and a row with no blocks yet paints an
  ;; empty state whose button starts the first one. OPEN_DRAFT is the
  ;; document-first entry: same payload, but it lands in the editor. SAVE
  ;; emits BLOCKS_SAVED for the host's persistor; this atom never fetches or
  ;; persists.
  trait BlockEdit -> @rebindable Document [interaction, instance] {
    initial: idle

    state idle {
      INIT -> idle
      OPEN -> viewing when [">", (array/len ?blocksJson), 0]
        (set @entity.id ?id)
        (set @entity.blocksJson ?blocksJson)
        (render-ui main {
          children: [{
            children: [{
              action: EDIT_BLOCKS
              icon: edit
              label: @config.editLabel
              type: button
              variant: secondary
            }]
            direction: horizontal
            gap: sm
            justify: end
            type: stack
          }, {
            action: EDIT_BLOCKS
            children: [{
              initialBlocks: @entity.blocksJson
              readOnly: true
              type: rich-block-editor
            }]
            className: "cursor-text rounded-md transition-colors hover:bg-muted/40"
            type: box
          }]
          direction: vertical
          gap: sm
          type: stack
        })
      OPEN -> viewing when ["=", (array/len ?blocksJson), 0]
        (set @entity.id ?id)
        (set @entity.blocksJson ?blocksJson)
        (render-ui main {
          actionEvent: EDIT_BLOCKS
          actionLabel: @config.emptyActionLabel
          description: @config.emptyDescription
          icon: file-text
          title: @config.emptyTitle
          type: empty-state
        })
      ;; Document-first entry: the row was just minted as a blank draft, so
      ;; the body opens ALREADY authoring instead of painting an empty state
      ;; the author has to click through. A distinct trigger, not a flag on
      ;; OPEN — the guard surface stays decidable.
      OPEN_DRAFT -> editing
        (set @entity.id ?id)
        (set @entity.blocksJson ?blocksJson)
        (render-ui main {
          children: [{
            align: center
            children: [{ name: file-text, type: icon }, {
              content: @config.title
              type: typography
              variant: h4
            }]
            direction: horizontal
            gap: sm
            type: stack
          }, {
            changeEvent: BLOCKS_CHANGE
            initialBlocks: @entity.blocksJson
            placeholder: @config.placeholder
            showToolbar: true
            type: rich-block-editor
          }, {
            children: [{
              action: SAVE_BLOCKS
              label: Save
              type: button
              variant: primary
            }, {
              action: CLOSE
              label: Cancel
              type: button
              variant: ghost
            }]
            direction: horizontal
            gap: sm
            justify: end
            type: stack
          }]
          direction: vertical
          gap: md
          type: stack
        })
      ;; self-loop on the external emit so the validator sees an in-atom
      ;; listener — the real consumer is the composing organism's persistor.
      BLOCKS_SAVED -> idle
    }

    state viewing {
      OPEN_DRAFT -> editing
        (set @entity.id ?id)
        (set @entity.blocksJson ?blocksJson)
        (render-ui main {
          children: [{
            align: center
            children: [{ name: file-text, type: icon }, {
              content: @config.title
              type: typography
              variant: h4
            }]
            direction: horizontal
            gap: sm
            type: stack
          }, {
            changeEvent: BLOCKS_CHANGE
            initialBlocks: @entity.blocksJson
            placeholder: @config.placeholder
            showToolbar: true
            type: rich-block-editor
          }, {
            children: [{
              action: SAVE_BLOCKS
              label: Save
              type: button
              variant: primary
            }, {
              action: CLOSE
              label: Cancel
              type: button
              variant: ghost
            }]
            direction: horizontal
            gap: sm
            justify: end
            type: stack
          }]
          direction: vertical
          gap: md
          type: stack
        })
      OPEN -> viewing when [">", (array/len ?blocksJson), 0]
        (set @entity.id ?id)
        (set @entity.blocksJson ?blocksJson)
        (render-ui main {
          children: [{
            children: [{
              action: EDIT_BLOCKS
              icon: edit
              label: @config.editLabel
              type: button
              variant: secondary
            }]
            direction: horizontal
            gap: sm
            justify: end
            type: stack
          }, {
            action: EDIT_BLOCKS
            children: [{
              initialBlocks: @entity.blocksJson
              readOnly: true
              type: rich-block-editor
            }]
            className: "cursor-text rounded-md transition-colors hover:bg-muted/40"
            type: box
          }]
          direction: vertical
          gap: sm
          type: stack
        })
      OPEN -> viewing when ["=", (array/len ?blocksJson), 0]
        (set @entity.id ?id)
        (set @entity.blocksJson ?blocksJson)
        (render-ui main {
          actionEvent: EDIT_BLOCKS
          actionLabel: @config.emptyActionLabel
          description: @config.emptyDescription
          icon: file-text
          title: @config.emptyTitle
          type: empty-state
        })
      EDIT_BLOCKS -> editing
        (render-ui main {
          children: [{
            align: center
            children: [{ name: file-text, type: icon }, {
              content: @config.title
              type: typography
              variant: h4
            }]
            direction: horizontal
            gap: sm
            type: stack
          }, {
            changeEvent: BLOCKS_CHANGE
            initialBlocks: @entity.blocksJson
            placeholder: @config.placeholder
            showToolbar: true
            type: rich-block-editor
          }, {
            children: [{
              action: SAVE_BLOCKS
              label: Save
              type: button
              variant: primary
            }, {
              action: CLOSE
              label: Cancel
              type: button
              variant: ghost
            }]
            direction: horizontal
            gap: sm
            justify: end
            type: stack
          }]
          direction: vertical
          gap: md
          type: stack
        })
    }

    state editing {
      BLOCKS_CHANGE -> editing
        (set @entity.blocksJson ?blocks)
      SAVE_BLOCKS -> viewing
        (emit BLOCKS_SAVED { id: @entity.id, blocksJson: @entity.blocksJson })
        (render-ui main {
          children: [{
            children: [{
              action: EDIT_BLOCKS
              icon: edit
              label: @config.editLabel
              type: button
              variant: secondary
            }]
            direction: horizontal
            gap: sm
            justify: end
            type: stack
          }, {
            action: EDIT_BLOCKS
            children: [{
              initialBlocks: @entity.blocksJson
              readOnly: true
              type: rich-block-editor
            }]
            className: "cursor-text rounded-md transition-colors hover:bg-muted/40"
            type: box
          }]
          direction: vertical
          gap: sm
          type: stack
        })
      CLOSE -> viewing
        (render-ui main {
          children: [{
            children: [{
              action: EDIT_BLOCKS
              icon: edit
              label: @config.editLabel
              type: button
              variant: secondary
            }]
            direction: horizontal
            gap: sm
            justify: end
            type: stack
          }, {
            action: EDIT_BLOCKS
            children: [{
              initialBlocks: @entity.blocksJson
              readOnly: true
              type: rich-block-editor
            }]
            className: "cursor-text rounded-md transition-colors hover:bg-muted/40"
            type: box
          }]
          direction: vertical
          gap: sm
          type: stack
        })
    }

    emits {
      BLOCKS_SAVED -> external {
        id : string!
        blocksJson : [BlockSpec]
      }
        @description "Signals a row's block content is ready to persist. This atom never persists — the composing organism routes BLOCKS_SAVED into its own persistor's update event."
        @synonyms "saved, persist, update, commit"
        @tier "domain"
      CLOSE
        @description "Leaves the editor without saving; the body returns to its read-only render."
        @synonyms "dismiss, hide, cancel, close"
        @tier "domain"
      BLOCKS_CHANGE {
        blocks : [BlockSpec]
      }
        @description "Signals that the content of a block has been modified while editing."
        @synonyms "update, modify, changed, edit"
        @tier "domain"
    }

    listens {
      OPEN {
        id : string!
        blocksJson : [BlockSpec]
      }
        @description "Hands the editor the row whose body it renders — the caller supplies the row's id and current blocks, since this trait never fetches them itself. Re-firing it repaints the body (e.g. after the host refetches a saved row)."
        @synonyms "show, launch, reveal, edit"
        @tier "domain"
      OPEN_DRAFT {
        id : string!
        blocksJson : [BlockSpec]
      }
        @description "Hands the editor a row that was just created as a blank draft: same payload as OPEN, but the body opens straight in the authoring editor instead of the read-only render, so a document-first 'New page' lands the author on a cursor rather than an empty state."
        @synonyms "new document, start writing, blank draft, compose"
        @tier "domain"
      BLOCKS_CHANGE {
        blocks : [BlockSpec]
      }
        @description "Indicates changes to the content of editable blocks while editing."
        @synonyms "update, modify, edit"
        @tier "domain"
      CLOSE
        @description "Leaves the editor without saving; the body returns to its read-only render."
        @synonyms "dismiss, hide, cancel, close"
        @tier "domain"
    }

    config {
      title : string = "Edit content"
        @label "Editor heading"
        @description "Heading shown above the editor while the body is being edited."
        @tier "presentation"
      placeholder : string = "Start writing…"
        @label "Placeholder text"
        @description "Placeholder shown in the block editor when it is empty."
        @tier "presentation"
      editLabel : string = "Edit content"
        @label "Edit button label"
        @description "Label of the button above the read-only body that opens the editor."
        @tier "presentation"
      emptyTitle : string = "Nothing written yet"
        @label "Empty heading"
        @description "Heading shown in place of the body when the row has no blocks yet."
        @tier "presentation"
      emptyDescription : string = "This page has no content yet. Start writing to fill it in."
        @label "Empty description"
        @description "Supporting line shown with the empty body state."
        @tier "presentation"
      emptyActionLabel : string = "Start writing"
        @label "Empty action label"
        @description "Label of the button that opens the editor from the empty body state."
        @tier "presentation"
    }
  }

  page "/documents/edit" as DocumentEditPage -> DocumentEdit
  page "/documents/block-edit" as BlockEditPage -> BlockEdit
}
